\label{thm:weighted}
For every integer $d\ge1$, there is a constant $c_d>0$ such that, for every
finite positive Borel measure $\mu$ with compact support satisfying
$\operatorname{diam}(\operatorname{supp}\mu)\le1$ and every $0<\varepsilon<1$,
\begin{equation}
  \mathcal N_\varepsilon(\mu)
  \ge
  c_d\varepsilon^{(d-1)/2}\mathcal A_\varepsilon(\mu).
  \label{eq:weighted-main-bound}
\end{equation}

\label{cor:main}
For every integer $d\ge1$, there is a constant $c_d>0$ such that, for every
finite $P\subset\mathbb R^d$ with $\operatorname{diam}(P)\le1$ and every $0<\varepsilon<1$,
\begin{equation}
  \mathcal N_\varepsilon(P)
  \ge
  c_d\varepsilon^{(d-1)/2}\mathcal A_\varepsilon(P).
  \label{eq:main-bound}
\end{equation}

\label{lem:biconvex}
Suppose that $K$ is biconvex and that there is $R>0$ such that
\begin{equation}
  |E|\,\#X\le R
  \label{eq:rectangle-condition}
\end{equation}
whenever $E\subset I$ is measurable, $X\subset\mathcal J$, and $K=1$
on $E\times X$.  Then
\[
  T_Kc(s):=\sum_{a\in\mathcal J}c_aK(s,a)
\]
satisfies
\begin{equation}
  \|T_Kc\|_{L^2(I)}
  \le4\sqrt R\,\|c\|_{\ell^2(\mathcal J)}.
  \label{eq:biconvex-norm}
\end{equation}

\label{prop:one-dimensional}
Let $f:[-1,1]\to\mathbb R$ be continuous and convex, let $\delta>0$, let
$\Lambda\subset\delta\mathbb Z$ be finite, and let $\eta\ge0$.  Then
\[
  T_fc(s):=\sum_{a\in\Lambda}c_a
  \1_{\{\mathcal F_f(s,a)\le\eta\}}
\]
satisfies
\begin{equation}
  \|T_fc\|_{L^2([-1,1])}
  \le
  C\left(1+\frac{\eta}{\delta}\right)^{1/2}
  \|c\|_{\ell^2(\Lambda)},
  \label{eq:one-dimensional-bound}
\end{equation}
where $C$ is an absolute constant.

\label{prop:cap-bound}
Let $d\ge2$, let $K\subset\mathbb R^d$ be compact and convex, let $\delta>0$,
let $\Gamma\subset\delta\mathbb Z^d\cap K$ be finite, and let $\tau>0$.
Define
\[
  \mathcal C_{K,\tau}c(u)
  :=\sum_{z\in\Gamma}c_z\1_{\Omega_K(z,\tau)}(u).
\]
Then
\begin{equation}
  \|\mathcal C_{K,\tau}c\|_{L^2(S^{d-1},d\sigma)}
  \le
  C_d\left(1+\frac{\tau}{\delta}\right)^{d/2}
  \|c\|_{\ell^2(\Gamma)},
  \label{eq:cap-bound}
\end{equation}
where $C_d$ depends only on $d$.

\label{lem:common-directions}
Let $B\subset\mathbb R^d$ be compact and convex with
$\operatorname{diam}(B)\le\Delta$, and let $z,w\in B$ with $r:=|z-w|>0$.  Put
$v:=(z-w)/r$.  Then, for every $u\in S^{d-1}$,
\begin{equation}
\begin{aligned}
 &[h_B(u)-z\cdot u]+[h_B(-u)+w\cdot u]\\
 &\qquad
 =w_B(u)-r\cos\angle(u,v)
 \le\Delta-r\cos\angle(u,v).
\end{aligned}
\label{eq:deficit-width-inequality}
\end{equation}
In particular, if $\Delta-r\le\kappa$, $0<\rho\le1$, and
\begin{equation}
  \kappa+\frac{\Delta\rho^2}{2}\le\tau,
  \label{eq:common-direction-condition}
\end{equation}
then the geodesic ball of radius $\rho$ about $v$ is contained in
\[
  \Omega_B(z,\tau)\cap\bigl(-\Omega_B(w,\tau)\bigr).
\]
